        { t: "mcq", q: "“Don't open the door to strangers,” Mum told us. → Mum told us ____ the door to strangers.", o: ["not open", "don't open", "to opening", "not to open"], a: 3, x: "النهي المنقول: tell + مفعول + not to + مصدر." },
        { t: "mcq", q: "“Can you swim?” the lifeguard asked him. → The lifeguard asked him ____.", o: ["that he can swim", "if could he swim", "if he could swim", "whether can he swim"], a: 2, x: "سؤال نعم/لا ← if أو whether + ترتيب خبري، وcan تتراجع إلى could: if he could swim." },
        { t: "mcq", q: "“I would have called if I had known,” Sami said. → Sami said that he ____ if he had known.", o: ["would call", "will have called", "had called", "would have called"], a: 3, x: "الشرط الثالث لا يتغير في الكلام المنقول: would have called … if he had known." },
        { t: "mcq", q: "“I wish I had a bigger room,” Lina said. → Lina said that she ____ a bigger room.", o: ["wishes she has", "wished she had", "had wished she had had", "wished she would have"], a: 1, x: "wish + past simple صيغة ماضٍ أصلاً فلا تتراجع؛ يتغير wish إلى wished فقط." },
        { t: "gap", q: "“Where are you going?” Dad asked me. → Dad asked me where ____.", a: ["I was going"], x: "ترتيب خبري بلا inversion، وpresent continuous تتراجع إلى past continuous: I was going." },
        { t: "gap", q: "“We have been waiting for hours,” the passengers complained. → The passengers complained that they ____ for hours.", a: ["had been waiting"], x: "present perfect continuous ← past perfect continuous: had been waiting." },
        { t: "gap", q: "“Tomorrow I'll start my revision,” said Hala. → Hala said she would start her revision ____.", a: ["the next day", "the following day", "the day after", "on the next day", "on the following day", "on the day after"], x: "tomorrow ← the next day / the following day / the day after." },
        { t: "gap", q: "“I wish you would stop tapping your pen,” said Dana. → Dana said she wished I ____ tapping my pen.", a: ["would stop"], x: "wish + would تبقى would في الكلام المنقول؛ فلا نُرجعها." },
        { t: "tr", q: "“Why didn't you reply to my message?” Nadia asked me.", p: "Rewrite starting with: Nadia asked me …", a: ["Nadia asked me why I hadn't replied to her message.", "Nadia asked me why I had not replied to her message.", "Nadia asked me why I didn't reply to her message.", "Nadia asked me why I did not reply to her message."], x: "سؤال بأداة استفهام: ترتيب خبري بلا did، وpast simple تتراجع إلى past perfect (hadn't replied)، وyou ← I وmy ← her." },
        { t: "tr", q: "“Shall I switch off the lights?” Amal said to her mother.", p: "Rewrite starting with: Amal asked her mother …", a: ["Amal asked her mother if she should switch off the lights.", "Amal asked her mother whether she should switch off the lights.", "Amal asked her mother if she should switch the lights off.", "Amal asked her mother whether she should switch the lights off."], x: "shall في عرض أو استئذان ← should في الكلام المنقول، والسؤال نعم/لا ← if / whether." },
        { t: "tr", q: "“I'll be waiting for you here at eight,” Tariq said to me.", p: "Rewrite starting with: Tariq told me …", a: ["Tariq told me he would be waiting for me there at eight.", "Tariq told me that he would be waiting for me there at eight.", "Tariq told me he'd be waiting for me there at eight.", "Tariq told me that he'd be waiting for me there at eight."], x: "will be waiting ← would be waiting، وyou ← me، وhere ← there." },
        { t: "err", q: "She asked me where was the nearest pharmacy.", w: "was", c: "move it after “pharmacy” (where the nearest pharmacy was)", x: "في السؤال المنقول يعود الترتيب إلى فاعل + فعل: where the nearest pharmacy was." },
        { t: "err", q: "He told that he had never been to Aqaba.", w: "told", c: "said", x: "tell يحتاج إلى مفعول (told me that…)، فبدونه نستعمل said that…" },
        { t: "order", a: "She asked me whether I had finished my homework.", x: "سؤال نعم/لا منقول: whether + فاعل + فعل، وpast simple تتراجع إلى past perfect." },
        { t: "order", a: "He said he wished he had known the answer.", x: "wish + had + V3 (تمنٍّ عن الماضي): يتغير wish إلى wished فقط ويبقى ما بعده بلا تراجع إضافي." }
